from __future__ import annotations

TREND_TOLERANCE = 5

REQUIRED_FIELDS = ("values", "timestamps", "expected_step", "hard_limit")

# Deviation thresholds (inclusive lower bounds) used to classify a single
# sample as clean / minor / moderate / severe / invalid.
MINOR_THRESHOLD = 3
MODERATE_THRESHOLD = 6
SEVERE_THRESHOLD = 12

# Per-sample penalty scores. INVALID penalty is also used as the pass/fail
# cutoff in `_verdict`.
MINOR_SCORE = 3
MODERATE_SCORE = 10
SEVERE_SCORE = 25
INVALID_SCORE = 100


def qc_series(raw: object) -> dict:
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}
    values = raw["values"]
    timestamps = raw["timestamps"]
    gaps = _count_gaps(timestamps, raw["expected_step"])
    deviations = _deviations(values)
    labels, total, worst = classify_spikes(deviations, raw["hard_limit"])
    return {
        "ok": True,
        "labels": labels,
        "gaps": gaps,
        "score": total,
        "verdict": _verdict(total),
        "counts": _label_counts(labels),
        "trend": _trend(values),
        "streak": _longest_run(labels),
        "line": _summary_line(len(values), gaps, worst, total),
    }


def _validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
