    if s>=3:return "minor"
    return "clean"

def ref_verdict(total):
    if total>=100:return "fail"
    if total>=25:return "warn"
    return "pass"

def ref_qc(raw):
    if not isinstance(raw,dict): return {"ok":False,"error":"malformed input"}
    for k in ("values","timestamps","expected_step","hard_limit"):
        if k not in raw: return {"ok":False,"error":"missing field"}
    if not isinstance(raw["values"],list) or len(raw["values"])==0:return {"ok":False,"error":"bad values"}
    if not isinstance(raw["timestamps"],list) or len(raw["timestamps"])!=len(raw["values"]):return {"ok":False,"error":"bad timestamps"}
    for v,s in zip(raw["values"],raw["timestamps"]):
        if not isinstance(v,int) or not isinstance(s,int):return {"ok":False,"error":"bad sample"}
    ts=raw["timestamps"]
    for i in range(1,len(ts)):
        if ts[i]<=ts[i-1]:return {"ok":False,"error":"unordered timestamps"}
    es,hl=raw["expected_step"],raw["hard_limit"]
    if not isinstance(es,int) or es<=0:return {"ok":False,"error":"bad step"}
    if not isinstance(hl,int) or hl<=0:return {"ok":False,"error":"bad limit"}
    vals=raw["values"]
    gaps=sum(1 for i in range(1,len(ts)) if ts[i]-ts[i-1]>es)
    devs=[]
    for i in range(len(vals)):
        p=vals[i-1] if i>0 else vals[i]
        f=vals[i+1] if i+1<len(vals) else vals[i]
        m=sorted([p,vals[i],f])[1]
        devs.append(abs(vals[i]-m))
    labels,total,worst=ref_classify(devs,hl)
    delta=vals[-1]-vals[0]
    trend="rising" if delta>5 else ("falling" if delta<-5 else "stable")
    def run(labels):
        longest=cur=0
        for l in labels:
            if l=="clean":cur=0
            else: cur+=1; longest=max(longest,cur)
        return longest
    cnt={"clean":0,"minor":0,"moderate":0,"severe":0,"invalid":0}
    for l in labels:cnt[l]+=1
    line="n="+str(len(vals))+";gaps="+str(gaps)+";worst="+ref_worst(worst)+";score="+str(total)
    return {"ok":True,"labels":labels,"gaps":gaps,"score":total,"verdict":ref_verdict(total),
            "counts":cnt,"trend":trend,"streak":run(labels),"line":line}

random.seed(1)
for _ in range(20000):
    n=random.randint(1,15)
    hard=random.randint(1,120)
    devs=[random.randint(0,150) for _ in range(n)]
    assert q.classify_spikes(devs,hard)==ref_classify(devs,hard),(devs,hard)
