    assert q._verdict(s)==ref_verdict(s),(s,q._verdict(s),ref_verdict(s))

for _ in range(20000):
    vals=[random.randint(0,30) for _ in range(random.randint(1,12))]
    ts=[random.randint(0,1000)]
    for i in range(1,len(vals)): ts.append(ts[-1]+random.randint(1,8))
